const reserveRecordingRenderObject = `-- name: ReserveRecordingRenderObject :one
with authorized as (
    select inputs.render_job_id
    from recording_render_inputs inputs
    join recording_jobs jobs on jobs.id = inputs.render_job_id
    where inputs.render_input_handle = $6
      and inputs.tenant_id = $3
      and inputs.space_id = $14
      and inputs.episode_id = $4
      and inputs.recording_id = $5
      and inputs.render_job_id = $15
      and inputs.object_handle = $7
      and inputs.attempt_count = $8
      and inputs.fencing_generation = $9
      and inputs.capture_epoch = $10
      and inputs.envelope_digest = $11
      and inputs.key_handle = $16
      and jobs.kind = 'render'
      and jobs.state = 'leased'
      and jobs.lease_token = $17
      and jobs.lease_owner = $18
      and jobs.lease_expires_at = $19
      and jobs.lease_expires_at > clock_timestamp()
    for update of jobs
), next_version as (
    select coalesce(max(allocation_version), 0) + 1 as value
    from recording_render_object_allocations
    where recording_id = $5
)
insert into recording_render_object_allocations (
    id, reservation_request_id, allocation_version, tenant_id, episode_id,
    recording_id, render_job_id, render_input_handle, object_handle,
    attempt_count, fencing_generation, capture_epoch, envelope_digest,
    purpose, state, object_key
)
select $1, $2, next_version.value,
    $3, $4, $5,
    authorized.render_job_id, $6, $7,
    $8, $9, $10,
    $11, $12, 'reserved', $13
from authorized, next_version
returning id, reservation_request_id, allocation_version, tenant_id, episode_id, recording_id, render_job_id, render_input_handle, object_handle, attempt_count, fencing_generation, capture_epoch, envelope_digest, purpose, state, object_key, expected_content_type, expected_byte_size, expected_sha256, expected_duration_millis, upload_token_hash, upload_expires_at, object_version, object_etag, object_content_type, object_byte_size, object_sha256, committed_at, created_at
`

